prisma.$use(async (params, next) => {
  if (params.model === 'VolunteerProfile' && params.action === 'update') {
    const result = await next(params);
    const userId = params.args.where.userId;
    if (userId) {
      const profile = await prisma.volunteerProfile.findUnique({ where: { userId } });
      if (profile) {
        await prisma.user.update({ where: { id: userId }, data: { totalHours: profile.totalHours } });
      }
    }
    return result;
  }
  return next(params);
});

